from __future__ import annotations

import re
from dataclasses import dataclass


_IDENTIFIER = r"[0-9A-Za-z-]+"
_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-(" + _IDENTIFIER + r"(?:\." + _IDENTIFIER + r")*))?"
    r"(?:\+(" + _IDENTIFIER + r"(?:\." + _IDENTIFIER + r")*))?"
)


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


@dataclass(frozen=True)
class _Comparator:
    operator: str
    version: Version


def _is_numeric_identifier(identifier: str) -> bool:
    return identifier.isascii() and identifier.isdigit()


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise ValueError(f"invalid version: {text!r}")

    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")

    major, minor, patch, prerelease_text, build_text = match.groups()
    prerelease = tuple(prerelease_text.split(".")) if prerelease_text else ()
    for identifier in prerelease:
        if (
            _is_numeric_identifier(identifier)
            and len(identifier) > 1
            and identifier[0] == "0"
        ):
            raise ValueError(f"invalid version: {text!r}")

    build = tuple(build_text.split(".")) if build_text else ()
    return Version(int(major), int(minor), int(patch), prerelease, build)


def _as_version(value: str | Version) -> Version:
    if isinstance(value, Version):
        return value
    if isinstance(value, str):
        return parse(value)
    raise ValueError(f"invalid version: {value!r}")


def _compare_identifiers(a: str, b: str) -> int:
    a_numeric = _is_numeric_identifier(a)
    b_numeric = _is_numeric_identifier(b)

    if a_numeric and b_numeric:
        a_digits = a.lstrip("0")
        b_digits = b.lstrip("0")
        if len(a_digits) != len(b_digits):
            return -1 if len(a_digits) < len(b_digits) else 1
        if a_digits == b_digits:
            return 0
        return -1 if a_digits < b_digits else 1

    if a_numeric:
        return -1
    if b_numeric:
        return 1
    if a == b:
        return 0
    return -1 if a < b else 1


def _compare_versions(a: Version, b: Version) -> int:
    if a.major != b.major:
        return -1 if a.major < b.major else 1
    if a.minor != b.minor:
        return -1 if a.minor < b.minor else 1
    if a.patch != b.patch:
        return -1 if a.patch < b.patch else 1

    if not a.prerelease and not b.prerelease:
        return 0
    if not a.prerelease:
        return 1
    if not b.prerelease:
        return -1

    for a_identifier, b_identifier in zip(a.prerelease, b.prerelease):
        result = _compare_identifiers(a_identifier, b_identifier)
        if result != 0:
            return result

    if len(a.prerelease) == len(b.prerelease):
        return 0
    return -1 if len(a.prerelease) < len(b.prerelease) else 1


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    return _compare_versions(_as_version(a), _as_version(b))


def _parse_comparator(token: str) -> _Comparator:
    for operator in (">=", "<=", "^", "~", ">", "<", "="):
        if token.startswith(operator):
            version_text = token[len(operator) :]
            if not version_text:
                raise ValueError(f"invalid range: dangling operator in {token!r}")
            return _Comparator(operator, parse(version_text))

    return _Comparator("=", parse(token))


def _parse_range(range_: str) -> list[list[_Comparator]]:
    if not isinstance(range_, str):
        raise ValueError(f"invalid range: {range_!r}")

    comparator_sets: list[list[_Comparator]] = []
    for alternative in range_.split("||"):
        tokens = alternative.split()
        if not tokens:
            raise ValueError(f"invalid range: empty comparator set in {range_!r}")
        comparator_sets.append([_parse_comparator(token) for token in tokens])

    return comparator_sets


def _caret_upper_bound(version: Version) -> Version:
    if version.major != 0:
        return Version(version.major + 1, 0, 0)
    if version.minor != 0:
        return Version(0, version.minor + 1, 0)
    return Version(0, 0, version.patch + 1)


def _satisfies_comparator(version: Version, comparator: _Comparator) -> bool:
    operator = comparator.operator
    expected = comparator.version
    result = _compare_versions(version, expected)

    if operator == "=":
        return result == 0
    if operator == ">":
        return result > 0
    if operator == ">=":
        return result >= 0
    if operator == "<":
        return result < 0
    if operator == "<=":
        return result <= 0

    if result < 0:
        return False
    if operator == "^":
        upper = _caret_upper_bound(expected)
    else:  # operator == "~"
        upper = Version(expected.major, expected.minor + 1, 0)
    return _compare_versions(version, upper) < 0


def _satisfies_set(version: Version, comparators: list[_Comparator]) -> bool:
    if version.prerelease:
        prerelease_allowed = any(
            comparator.version.prerelease
            and (
                comparator.version.major,
                comparator.version.minor,
                comparator.version.patch,
            )
            == (version.major, version.minor, version.patch)
            for comparator in comparators
        )
        if not prerelease_allowed:
            return False

    return all(_satisfies_comparator(version, comparator) for comparator in comparators)


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    parsed_version = _as_version(version)
    comparator_sets = _parse_range(range_)
    return any(
        _satisfies_set(parsed_version, comparators)
        for comparators in comparator_sets
    )

