import random
import string
import sys

sys.path.insert(0, "/private/tmp/tmpsv1tu4fb/pete/projects/devkit")
from devkit.semver import Version, compare, parse, satisfies

rng = random.Random(0)


def ident(numeric=False):
    if numeric:
        return str(rng.randrange(0, 10 ** rng.randrange(1, 12)))
    chars = string.ascii_letters + string.digits + "-"
    while True:
        s = "".join(rng.choice(chars) for _ in range(rng.randrange(1, 10)))
        if not (s.isdigit() and len(s) > 1 and s[0] == "0"):
            return s


count = 0
for _ in range(5000):
    text = f"{rng.randrange(0, 10**6)}.{rng.randrange(0, 10**6)}.{rng.randrange(0, 10**6)}"
    if rng.random() < 0.5:
        text += "-" + ".".join(ident(rng.random() < 0.5) for _ in range(rng.randrange(1, 5)))
    if rng.random() < 0.5:
        text += "+" + ".".join(ident(False) for _ in range(rng.randrange(1, 5)))
    v = parse(text)
    assert str(v) == text, (text, str(v))
    assert compare(v, text) == 0
    count += 1

for _ in range(3000):
    a = parse(
        f"{rng.randrange(4)}.{rng.randrange(4)}.{rng.randrange(4)}"
        + ("-" + ident() if rng.random() < 0.5 else "")
    )
    b = parse(str(a) + ("+x.y" if rng.random() < 0.5 else ""))
    assert compare(a, b) == 0
    c = parse(
        f"{rng.randrange(4)}.{rng.randrange(4)}.{rng.randrange(4)}"
        + ("-" + ident() if rng.random() < 0.5 else "")
    )
    assert compare(a, c) == -compare(c, a)

print("random checks passed:", count)

for op in ("^", "~"):
    for base in ("1.2.3", "0.2.3", "0.0.3", "0.0.0", "2.0.0"):
        for v in (base, "0.0.0", "1.0.0", "2.0.0", "0.3.0", "0.0.4", "1.3.0", "0.1.0"):
            assert isinstance(satisfies(v, op + base), bool)
print("boundary spot checks passed")
